local config = {
  ui_story_30680601_1_dialog_content = "Sigh... Am I already out of spending money for the month?",
  ui_story_30680601_2_dialog_content = "I don't get to come shopping in Umbraton very often...",
  ui_story_30680601_3_dialog_content = "I really wanted to buy that board game Gronru told me about the last time I saw her.",
  ui_story_30680601_4_dialog_content = "Maybe I could use some of the money Vice gave me for supplies...?",
  ui_story_30680601_5_dialog_content = "No! No way! Just the other day she was lecturing me.",
  ui_story_30680601_6_dialog_content = "\"Don't spend money on things we don't need! Just the essentials!\"",
  ui_story_30680601_7_dialog_content = "\"With healthy spending habits, our financial situation on Soroz will only get better and better!\"",
  ui_story_30680601_8_dialog_content = "Vice tries so hard to watch over our expenses. I shouldn't squander our hard-earned money!",
  ui_story_30680601_9_dialog_content = "You, over there! Don't move!",
  ui_story_30680601_10_dialog_content = "Yeah, you! Stay right where you are!",
  ui_story_30680601_11_dialog_content = "Huh? Who are you...",
  ui_story_30680601_12_dialog_content = "Wait, that voice... It's coming from above me!",
  ui_story_30680601_13_dialog_content = "That's right! It's everyone's favorite courier—Wendy, the cute and courageous Light Speed Spiral!",
  ui_story_30680601_14_dialog_content = "As for you, good sir, the look on your face says something must be troubling you!",
  ui_story_30680601_15_dialog_content = "Why not take one of my newspapers for yourself? All kinds of secret wisdom lie just within their pages!",
  ui_story_30680601_16_dialog_content = "I'm sure you'll find the answer to your problem in one of its many articles!",
  ui_story_30680601_17_dialog_content = "... What's going on here, Wendy? And why are you dressed like that?",
  ui_story_30680601_18_dialog_content = "Huh? Well, if it isn't PlayerName!",
  ui_story_30680601_19_dialog_content = "That outfit of yours...",
  ui_story_30680601_20_option_content = "It looks awesome!",
  ui_story_30680601_21_dialog_content = "Heehee! They don't call me the Light Speed Spiral for nothing!",
  ui_story_30680601_22_option_content = "It looks cute!",
  ui_story_30680601_23_dialog_content = "Really? You sure know how to flatter a girl, PlayerName!",
  ui_story_30680601_24_dialog_content = "I wear this uniform only when I'm out selling newspapers!",
  ui_story_30680601_25_dialog_content = "Say, I don't see Vice anywhere... Isn't she with you today?",
  ui_story_30680601_26_dialog_content = "She's still on Soroz. I came here to help her buy some supplies.",
  ui_story_30680601_27_dialog_content = "<size=33>What?! PlayerName without Vice... I can't believe my luck!</size>",
  ui_story_30680601_28_dialog_content = "What are you mumbling to yourself over there...?",
  ui_story_30680601_29_dialog_content = "Heehee... Nothing at all! Anyway, I'm working for the Umbraton branch of the Courier Union today.",
  ui_story_30680601_30_dialog_content = "They specifically asked me to come here and sell newspapers.",
  ui_story_30680601_31_dialog_content = "Makes sense, right? After all, I'm amazingly smart, talented, cute, and fast... I got tons of new readers from the Rediesel Desert subscribed to them!",
  ui_story_30680601_32_dialog_content = "And now I'm the sales champion!",
  ui_story_30680601_33_dialog_content = "Why don't you take one off my hands too, PlayerName? These things are worth their weight in gold!",
  ui_story_30680601_34_dialog_content = "H-Hold on...",
  ui_story_30680601_35_dialog_content = "Let me think about it for a second... I don't want to get scammed again!",
  ui_story_30680601_36_dialog_content = "You said you sold a bunch of newspapers in the Rediesel Desert, right?",
  ui_story_30680601_37_dialog_content = "As far as I know, the only people living there are the Rediesel Wrench.",
  ui_story_30680601_38_dialog_content = "But those guys are all the \"punch first, ask questions never\" types.",
  ui_story_30680601_39_dialog_content = "Do any of them out there actually read papers? I can't help but think you might be exaggerating a little...",
  ui_story_30680601_40_dialog_content = "The idea of someone like Brock sitting down to read the paper over a cup of tea... I don't think I can even imagine it.",
  ui_story_30680601_41_dialog_content = "Yep! Your suspicions are 100% correct!",
  ui_story_30680601_42_dialog_content = "Naturally, sending just anyone to sell newspapers to the Rediesel Wrench would be a humongous waste of time.",
  ui_story_30680601_43_dialog_content = "But I've always believed that the greater the challenge, the brighter I'll shine once I overcome it!",
  ui_story_30680601_44_dialog_content = "Don't forget, I'm a high-flying ballistic missile with the force of a small hurricane! Everywhere I go, I score a subscription rate of over 99%!",
  ui_story_30680601_45_dialog_content = "I refuse to believe that...",
  ui_story_30680601_46_dialog_content = "Tell me, did Sinsa pay for a subscription?",
  ui_story_30680601_47_dialog_content = "Of course! Sinsa was my very first customer, actually!",
  ui_story_30680601_48_dialog_content = "<size=42>Oh, Sinsaaaaaaa!</size>",
  ui_story_30680601_49_dialog_content = "Huh? Oh, hey, Wendy.",
  ui_story_30680601_50_dialog_content = "You're just in time, too. Did you bring me the latest issue of Shinnosuke Sinsa?",
  ui_story_30680601_51_dialog_content = "Nope! That won't be out until the end of the month.",
  ui_story_30680601_52_dialog_content = "Really? So what are you here for? Got a message for us or something?",
  ui_story_30680601_53_dialog_content = "Wrong again! Notice something different about me today?",
