  ui_story_30680601_57_dialog_content = "Could you stop talking about Eve for a few seconds, man?",
  ui_story_30680601_58_dialog_content = "I'm not here to deliver mail today.",
  ui_story_30680601_59_dialog_content = "So what are you here for, then?",
  ui_story_30680601_60_dialog_content = "Heehee, so... I got a special request from the Courier Union! I'm selling newspaper subscriptions today!",
  ui_story_30680601_61_dialog_content = "See? Look at all the different types! I bet there's even one for you in here, Sinsa!",
  ui_story_30680601_62_dialog_content = "Meh, not interested.",
  ui_story_30680601_63_dialog_content = "This ain't a Rediesel Wrench kind of thing, you know?",
  ui_story_30680601_64_dialog_content = "Besides... The only thing I'm interested in reading is Shinnosuke Sinsa.",
  ui_story_30680601_65_dialog_content = "One of my scouts just returned from a search, so I gotta go see what he found. Come back when they put out the newest issue of Shinnosuke Sinsa.",
  ui_story_30680601_66_dialog_content = "See you later.",
  ui_story_30680601_67_dialog_content = "... What if I told you I could give you an even better report than your scout?",
  ui_story_30680601_68_dialog_content = "Huh?",
  ui_story_30680601_69_dialog_content = "Don't believe me? Just see for yourself!",
