  ui_story_30680601_71_dialog_content = "And over here, you can see the latest trends in Umbraton and the state of the markets!",
  ui_story_30680601_72_dialog_content = "I bet you could learn all kinds of useful things just from these two articles alone!",
  ui_story_30680601_73_dialog_content = "... Gotta admit, sounds kinda enticing.",
  ui_story_30680601_74_dialog_content = "But how am I supposed to know whether the stuff here is true or not?",
  ui_story_30680601_75_dialog_content = "Easy! Just cross-reference it with the intel that your scouts bring back, and check the facts for yourself!",
  ui_story_30680601_76_dialog_content = "Oh, and look right here! It's the fashion column!",
  ui_story_30680601_77_dialog_content = "Just think about it! No girl could ever resist these cute clothes and accessories from around the world, and they're all right here!",
  ui_story_30680601_78_dialog_content = "I bet Eve would absolutely love them!",
  ui_story_30680601_79_dialog_content = "R-Really? You think Eve would be into this...?",
