  ui_story_30680601_97_dialog_content = "Hey! I'm talking to you here!",
  ui_story_30680601_98_dialog_content = "Hmm? Oh, it's just you, Wendy...",
  ui_story_30680601_99_dialog_content = "Sorry, guess I didn't notice you there. I'm doing some very important maintenance on the Rediesel Wrench's machines right now.",
  ui_story_30680601_100_dialog_content = "Geez... Never mind. You should subscribe to this newspaper!",
