  ui_story_30680601_104_dialog_content = "Pretty sure newspapers don't write about anything I'd be interested in.",
  ui_story_30680601_105_dialog_content = "Ugh... I should've known Fleur would be more challenging than Sinsa.",
  ui_story_30680601_106_dialog_content = "... Wait, I got it! You were cleaning up the machines just now, right?",
  ui_story_30680601_107_dialog_content = "Yep, and just look at them shine! Have you ever seen anything more beautiful?",
