  ui_story_30680601_121_dialog_content = "I guess you have a point...",
  ui_story_30680601_122_dialog_content = "But you took advantage of Fleur's feelings to sell your papers! Even if his feelings are for machines...",
  ui_story_30680601_123_dialog_content = "What about Roy? Someone as mature and frugal as him couldn't possibly have fallen for your tricks, right?",
  ui_story_30680601_124_dialog_content = "Hehe, sorry to disappoint you, but he's another satisfied customer!",
  ui_story_30680601_125_dialog_content = "Roooooooy!",
  ui_story_30680601_126_dialog_content = "Come buy a newspaper subscription, please? Just one!",
  ui_story_30680601_127_dialog_content = "Whatever you're up to, Wendy, I've got no time for it. I'm busy washing everyone's dishes.",
