  ui_story_30680601_143_dialog_content = "How do you know all that?",
  ui_story_30680601_144_dialog_content = "Does the Courier Union teach these things nowadays?",
  ui_story_30680601_145_dialog_content = "Not at all! Here, just take a look at this!",
  ui_story_30680601_146_dialog_content = "See? An entire column titled \"Hot Tips for Happy Housewives\"!",
  ui_story_30680601_147_dialog_content = "Say what now? \"Shine leather shoes with banana peels to make them look good as new...\"",
  ui_story_30680601_148_dialog_content = "\"Rub your hands with toothpaste or lard after chopping peppers to keep your fingers from burning...\"",
  ui_story_30680601_149_dialog_content = "\"Soak sweaters in hot water and air-dry them to restore elasticity to their sleeves and collars...\"?!",
  ui_story_30680601_150_dialog_content = "Th-This is... This is unbelievable!",
  ui_story_30680601_151_dialog_content = "So will you subscribe, Roy?",
  ui_story_30680601_152_dialog_content = "Yes, immediately!!",
  ui_story_30680601_153_dialog_content = "Not Roy too... I'm starting to lose faith in reality...",
  ui_story_30680601_154_dialog_content = "Your marketing skills are terrifying, Wendy!",
  ui_story_30680601_155_dialog_content = "The only other salesperson that could compete is Jomu!",
  ui_story_30680601_156_dialog_content = "Jomu, huh?",
  ui_story_30680601_157_dialog_content = "He purchased a year's subscription, you know?",
  ui_story_30680601_158_dialog_content = "Okay, there's no way I'm believing that.",
  ui_story_30680601_159_dialog_content = "Yo, Jomu!",
  ui_story_30680601_160_dialog_content = "Well, look who it is! Wendy, the brightest little bird in the entire desert!",
  ui_story_30680601_161_dialog_content = "Though, judging by your attire, I would guess you're here as a salesperson, not a customer... Correct?",
  ui_story_30680601_162_dialog_content = "Heehee, clever as always, Jomu!",
  ui_story_30680601_163_dialog_content = "Well, when such a powerful rival appears before you, it's not easy to simply ignore them.",
  ui_story_30680601_164_dialog_content = "But I should warn you... The parlor tricks you used on Sinsa and the others won't work against a business-savvy professional such as myself.",
  ui_story_30680601_165_dialog_content = "I would never dream of treating you like an ordinary customer, Jomu! I had something else in mind. Something like a partnership?",
  ui_story_30680601_166_dialog_content = "From what I've heard, you recently received a shipment of books, but you haven't found a suitable way to sell them.",
  ui_story_30680601_167_dialog_content = "I could market your books to the customers who purchase newspaper subscriptions from me.",
  ui_story_30680601_168_dialog_content = "Naturally, you would also need to subscribe, and your books would require a proper distribution channel as well.",
  ui_story_30680601_169_dialog_content = "It appears you've done your research.",
  ui_story_30680601_170_dialog_content = "When it comes to business, the best way to make money is when every party benefits.",
  ui_story_30680601_171_dialog_content = "And in the cruel world of business, whoever has information controls everything.",
  ui_story_30680601_172_dialog_content = "Since you've done such a thorough investigation into my dealings, I would be more than happy to do business with you... partner.",
  ui_story_30680601_173_dialog_content = "May this and any future endeavors prove fruitful for both of us.",
  ui_story_30680601_174_dialog_content = "Sorry to disappoint you, but our partnership-slash-rivalry is only temporary.",
  ui_story_30680601_175_dialog_content = "Once I finish this assignment for the Courier Union, I'm going back to my usual work!",
