  ui_story_30680601_177_dialog_content = "Alright, I give up...",
  ui_story_30680601_178_dialog_content = "I never thought Jomu would agree to something like this. Though I guess making deals IS his specialty.",
  ui_story_30680601_179_dialog_content = "Fine, I'll admit it: you really are a sales genius.",
  ui_story_30680601_180_dialog_content = "Finally coming around, huh? In that case, can I interest you in a newspaper subscription?",
  ui_story_30680601_181_dialog_content = "After all, it would be pretty rude of you if you didn't after I worked so hard to convince you...",
  ui_story_30680601_182_dialog_content = "Besides, don't you want to know more about that regular Caelestite column?",
  ui_story_30680601_183_dialog_content = "Oh, and just for your information, everyone in the Rediesel Wrench is reading the papers now!",
  ui_story_30680601_184_dialog_content = "You don't want to lag behind that bunch of knuckleheads, right?",
  ui_story_30680601_185_dialog_content = "Yeah, yeah, I get it!",
  ui_story_30680601_186_dialog_content = "Ugh. I'll have to come back for that board game some other time...",
  ui_story_30680601_187_dialog_content = "PlayerName—",
  ui_story_30680601_188_dialog_content = "V-Vice?!",
  ui_story_30680601_189_dialog_content = "What's been taking you so long? Hmm? Oh hey, Wendy!",
  ui_story_30680601_190_dialog_content = "Howdy, Vice! Can I interest you in a newspaper subscription?",
